<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/leaflet.draw/1.0.4/leaflet.draw.css">
<style>#mapLotes{height:650px;background:#fafafa}.lote-sidebar{height:650px;overflow:auto}.lote-item{cursor:pointer}.lote-resumen{padding:8px;border:1px solid #ddd;margin-bottom:5px;border-radius:4px}</style>
<section class="content-header"><h1><?php echo html_escape($proyecto['proyecto_nombre']); ?> <small>Mapa administrativo</small></h1></section>
<section class="content"><div class="row"><div class="col-md-3 lote-sidebar"><div class="box box-primary"><div class="box-header"><b>Plano</b></div><div class="box-body"><form method="post" enctype="multipart/form-data" action="<?php echo site_url('proyecto/subir_plano/'.$proyecto['proyecto_id']); ?>"><input type="file" name="proyecto_imagen" required><br><button class="btn btn-primary btn-sm">Subir / reemplazar</button></form></div></div><button class="btn btn-success btn-block" onclick="nuevoLote()"><i class="fa fa-plus"></i> Nuevo lote</button><br><select id="filtro_estado" class="form-control" onchange="cargarLotes()"><option value="">Todos</option><option>DISPONIBLE</option><option>RESERVADO</option><option>VENDIDO</option><option>BLOQUEADO</option></select><br><div id="resumen"></div><div class="list-group" id="lista"></div></div><div class="col-md-9"><div id="mapLotes"></div></div></div></section>
<div class="modal fade" id="modalLote"><div class="modal-dialog modal-lg"><div class="modal-content"><div class="modal-header"><button class="close" data-dismiss="modal">&times;</button><h4>Lote / Producto Ximpleman</h4></div><div class="modal-body"><form id="formLote"><input type="hidden" id="proyecto_lote_id" name="proyecto_lote_id"><input type="hidden" name="proyecto_id" value="<?php echo $proyecto['proyecto_id']; ?>"><input type="hidden" id="geojson" name="geojson"><div class="row"><div class="col-md-4"><label>Código</label><input class="form-control" id="lote_codigo" name="lote_codigo" required></div><div class="col-md-4"><label>UV</label><input class="form-control" id="uv" name="uv"></div><div class="col-md-4"><label>Manzano</label><input class="form-control" id="manzano" name="manzano"></div><div class="col-md-4"><label>Número</label><input class="form-control" id="numero" name="numero"></div><div class="col-md-4"><label>Superficie m²</label><input type="number" step="0.01" class="form-control" id="superficie" name="superficie"></div><div class="col-md-4"><label>Precio</label><input type="number" step="0.01" class="form-control" id="precio" name="precio"></div><div class="col-md-12"><label>Descripción</label><textarea class="form-control" id="descripcion" name="descripcion"></textarea></div></div></form><hr><div id="estado_actual"></div><div class="row"><div class="col-md-5"><label>Cliente para reserva</label><select id="cliente_id" class="form-control"><option value="">--Seleccione--</option><?php foreach($clientes as $c){ ?><option value="<?php echo $c['cliente_id']; ?>"><?php echo html_escape($c['cliente_nombre']); ?></option><?php } ?></select></div><div class="col-md-3"><label>Monto reserva</label><input id="monto_reserva" type="number" step="0.01" class="form-control"></div><div class="col-md-4"><label>Observación</label><input id="obs" class="form-control"></div></div><br><div id="historial"></div></div><div class="modal-footer"><button class="btn btn-primary" onclick="guardarLote()">Guardar lote</button><button class="btn btn-warning" onclick="reservar()">Reservar</button><button class="btn btn-default" onclick="liberar()">Liberar</button><a class="btn btn-success" href="<?php echo site_url('venta/ventas'); ?>"><i class="fa fa-shopping-cart"></i> Ir a Venta Ximpleman</a><button class="btn btn-danger" data-dismiss="modal">Cerrar</button></div></div></div></div>
<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/leaflet.draw/1.0.4/leaflet.draw.js"></script>
<script>
var site='<?php echo site_url(); ?>', pid=<?php echo (int)$proyecto['proyecto_id']; ?>, img='<?php echo base_url('uploads/planos/'.($proyecto['proyecto_imagen']?$proyecto['proyecto_imagen']:'')); ?>', w=<?php echo (float)$proyecto['imagen_ancho']; ?>, h=<?php echo (float)$proyecto['imagen_alto']; ?>;
var map=L.map('mapLotes',{crs:L.CRS.Simple,minZoom:-2}), bounds=[[0,0],[h,w]], items=new L.FeatureGroup(); if('<?php echo $proyecto['proyecto_imagen']; ?>')L.imageOverlay(img,bounds).addTo(map); map.fitBounds(bounds); map.addLayer(items); map.addControl(new L.Control.Draw({edit:{featureGroup:items},draw:{polygon:true,rectangle:true,polyline:false,circle:false,marker:false,circlemarker:false}})); var temporal=null;
function color(e){return e==='VENDIDO'?'#d9534f':e==='RESERVADO'?'#f0ad4e':e==='BLOQUEADO'?'#777':'#5cb85c'}
map.on(L.Draw.Event.CREATED,function(e){temporal=e.layer;items.addLayer(temporal);limpiar();$('#geojson').val(JSON.stringify(temporal.toGeoJSON()));$('#modalLote').modal('show')});
map.on(L.Draw.Event.EDITED,function(e){e.layers.eachLayer(function(x){if(x.loteId)$.post(site+'proyecto_lote/guardar_poligono',{lote_id:x.loteId,geojson:JSON.stringify(x.toGeoJSON())})})});
function limpiar(){$('#formLote')[0].reset();$('#proyecto_lote_id,#geojson').val('');$('#historial,#estado_actual').html('')}
function nuevoLote(){limpiar();temporal=null;$('#modalLote').modal('show')}
function cargarLotes(){items.clearLayers();$.getJSON(site+'proyecto_lote/listar/'+pid,{estado:$('#filtro_estado').val()},function(rs){var x='';$.each(rs,function(i,l){x+='<a class="list-group-item lote-item" onclick="abrir('+l.proyecto_lote_id+')"><b>'+l.lote_codigo+'</b><br>'+l.estado_actual+' | '+l.superficie+' m² | Bs '+Number(l.precio).toFixed(2)+'</a>';if(l.geojson){var g=L.geoJSON(JSON.parse(l.geojson),{style:{color:color(l.estado_actual),fillColor:color(l.estado_actual),fillOpacity:.45}});g.eachLayer(function(q){q.loteId=l.proyecto_lote_id;q.on('click',function(){abrir(l.proyecto_lote_id)});items.addLayer(q)})}});$('#lista').html(x);});$.getJSON(site+'proyecto_lote/resumen/'+pid,function(r){var x='';$.each(r,function(k,v){x+='<div class="lote-resumen"><b>'+k+'</b>: '+v.cantidad+'<br>Bs '+Number(v.total).toFixed(2)+'</div>'});$('#resumen').html(x)})}
function abrir(id){$.getJSON(site+'proyecto_lote/obtener/'+id,function(r){var l=r.lote;$('#proyecto_lote_id').val(l.proyecto_lote_id);$('#lote_codigo').val(l.lote_codigo);$('#uv').val(l.uv);$('#manzano').val(l.manzano);$('#numero').val(l.numero);$('#superficie').val(l.superficie);$('#precio').val(l.precio);$('#descripcion').val(l.descripcion);$('#geojson').val(l.geojson);$('#cliente_id').val(l.cliente_id);$('#estado_actual').html('<b>Estado:</b> '+l.estado_actual+' &nbsp; <b>Producto ID:</b> '+l.producto_id);var h='';$.each(r.historial,function(i,a){h+='<small>'+a.fecha_hora+' - '+a.accion+' - '+a.detalle+'</small><br>'});$('#historial').html(h);$('#modalLote').modal('show')})}
function guardarLote(){if(!$('#geojson').val()&&temporal)$('#geojson').val(JSON.stringify(temporal.toGeoJSON()));$.post(site+'proyecto_lote/guardar',$('#formLote').serialize(),function(r){alert(r.message);if(r.success){$('#modalLote').modal('hide');cargarLotes()}},'json')}
function reservar(){var id=$('#proyecto_lote_id').val();if(!id){alert('Primero guarde el lote');return}$.post(site+'proyecto_lote/reservar',{lote_id:id,cliente_id:$('#cliente_id').val(),monto:$('#monto_reserva').val(),observacion:$('#obs').val()},function(r){alert(r.message);if(r.success){$('#modalLote').modal('hide');cargarLotes()}},'json')}
function liberar(){var id=$('#proyecto_lote_id').val();if(!id)return;$.post(site+'proyecto_lote/liberar',{lote_id:id},function(r){alert(r.message);if(r.success){$('#modalLote').modal('hide');cargarLotes()}},'json')}
cargarLotes();
</script>